import pandas as pd
import numpy as np

# Define indicators
def macd(price, fast_period, slow_period, signal_period):
  ema_fast = price.ewm(span=fast_period, adjust=False).mean()
  ema_slow = price.ewm(span=slow_period, adjust=False).mean()
  macd_line = ema_fast - ema_slow
  signal_line = macd_line.ewm(span=signal_period, adjust=False).mean()
  return macd_line, signal_line

def williams_r(high, low, close, period):
  highest_high = high.rolling(window=period).max()
  lowest_low = low.rolling(window=period).min()
  wr = -100 * ((highest_high - close) / (highest_high - lowest_low))
  return wr

# Define trading strategy
class MomentumStrategy:
  def __init__(self, price, high, low, fast_period, slow_period, signal_period, wr_period, volatility_threshold, position_size, stop_loss_threshold, take_profit_threshold):
    self.price = price
    self.high = high
    self.low = low
    self.fast_period = fast_period
    self.slow_period = slow_period
    self.signal_period = signal_period
    self.wr_period = wr_period
    self.volatility_threshold = volatility_threshold
    self.position_size = position_size
    self.stop_loss_threshold = stop_loss_threshold
    self.take_profit_threshold = take_profit_threshold

  def generate_signals(self):
    macd_line, signal_line = macd(self.price, self.fast_period, self.slow_period, self.signal_period)
    wr = williams_r(self.high, self.low, self.price, self.wr_period)

    buy_signals = np.where((macd_line > signal_line) & (wr < -80), 1, 0)
    sell_signals = np.where((macd_line < signal_line) & (wr > -20), -1, 0)

    return buy_signals, sell_signals

  def calculate_position_size(self):
    volatility = self.price.pct_change().rolling(window=20).std() * np.sqrt(20)
    position_size = np.where(volatility > self.volatility_threshold, self.position_size, 0)
    return position_size

  def calculate_stop_loss(self):
    stop_loss = self.price * (1 - self.stop_loss_threshold)
    return stop_loss

  def calculate_take_profit(self):
    take_profit = self.price * (1 + self.take_profit_threshold)
    return take_profit

